fn all_characters_same(char_arr: &Vec<char>) -> bool {
    // If there are 0 or 1 elements, they trivially satisfy the condition.
    if char_arr.len() <= 1 {
        return true;
    }
    // Take the first character as the reference.
    let first = char_arr[0];
    // Check that every subsequent character matches the first.
    char_arr.iter().skip(1).all(|&c| c == first)
}

fn main() {
    let cases = vec![
        (vec![], true),
        (vec!['a'], true),
        (vec!['a', 'a', 'a'], true),
        (vec!['a', 'b', 'a'], false),
        (vec!['x', 'x', 'x', 'x'], true),
        (vec!['x', 'y'], false),
    ];

    for (input, expected) in cases {
        let result = all_characters_same(&input);
        println!(
            "all_characters_same({:?}) = {}, expected {}",
            input, result, expected
        );
        assert_eq!(result, expected);
    }
}